def sort_array(arr):
    """
    Sorts an array of integers according to the number of ones in their 
    binary representation in ascending order. For ties, sorts by decimal value.
    """
    def count_ones(n):
        n = abs(n)
        count = 0
        while n > 0:
            if n % 2 == 1:
                count += 1
            n //= 2
        return count

    def get_sort_key(x):
        return (count_ones(x), x)

    # Bubble sort implementation to avoid built-in sorting functions
    sorted_arr = list(arr)
    n = len(sorted_arr)

    for i in range(n):
        for j in range(0, n - i - 1):
            if get_sort_key(sorted_arr[j]) > get_sort_key(sorted_arr[j + 1]):
                sorted_arr[j], sorted_arr[j + 1] = sorted_arr[j + 1], sorted_arr[j]

    return sorted_arr
